# ============================================================
# APPLY
# ============================================================
for code in ["pt_pt", "es", "fr", "es_es", "fr_fr"]:
    # Read existing
    with open(f"langs/{code}.json", "r", encoding="utf-8") as f:
        existing = json.load(f)

    # Remove corrupted keys (not in pt_br)
    to_del = [k for k in existing if k not in PT_BR]
    for k in to_del:
        del existing[k]

    # Add missing keys
    for k in PT_BR:
        if k not in existing:
            existing[k] = k  # placeholder

    # Apply translations
    trans_dict = FR if code in ("fr", "fr_fr") else ES if code in ("es", "es_es") else None
    trans_ptbr = code == "pt_pt"  # use pt_br as base for pt_pt

    translated = 0
    for k, v in list(existing.items()):
        if k != v:
            continue
        if k.endswith(".py"):
            continue

        if trans_ptbr and k in PT_BR and PT_BR[k] != k:
            existing[k] = PT_BR[k]
            translated += 1
        elif trans_dict and k in trans_dict:
            existing[k] = trans_dict[k]
            translated += 1
        elif k in ("Auto-Patch", "Status", "Timestamp", "Tokens", "Tokens (cache)"):
            existing[k] = k  # universal term
            translated += 1

    # Write
    with open(f"langs/{code}.json", "w", encoding="utf-8") as f:
        json.dump(existing, f, ensure_ascii=False, indent=2)

    bad = sum(1 for k in existing if '",' in k)
    untrans = sum(1 for k, v in existing.items() if k == v and not k.endswith(".py"))
    print(f"{code}.json: {len(existing)} keys | corrupted:{bad} | untranslated:{untrans} | translated:{translated}")

# Make es==es_es and fr==fr_fr identical
for base, alias in [("es", "es_es"), ("fr", "fr_fr")]:
    with open(f"langs/{base}.json", "r", encoding="utf-8") as f:
        data = json.load(f)
    with open(f"langs/{alias}.json", "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"{alias}.json = {base}.json (identical copy)")

print("\nDone!")
